    severabilityDescription: 'ဤသဘောတူညီချက်၏ မည်သည့် ပြဋ္ဌာန်းချက်ကိုမဆို မမှန်ကန်ဟု သို့မဟုတ် အကောင်အထည်ဖော်၍ မရဟု တွေ့ရှိပါက၊ ထိုပြဋ္ဌာန်းချက်သည် ပျက်ပြယ်မည်ဖြစ်ပြီး၊ ကျန်ရှိသော ပြဋ္ဌာန်းချက်များသည် လုံးဝ အာဏာတည်နေပြီး ချုပ်နှောင်ထားမည် ဖြစ်သည်။',
    legalEffectDescription: 'ဤသဘောတူညီချက်သည် နှစ်ဖက်စလုံးအတွက် ဥပဒေအရ ချုပ်နှောင်ထားပြီး အမေရိကန် ပြည်ထောင်စုနှင့် ဥရောပတွင် လက်မှတ်ရေးထိုးနိုင်ပြီး အာဏာတည်နိုင်သည်။ နှစ်ဖက်စလုံးသည် ဤသဘောတူညီချက်ကို လက်မှတ်ရေးထိုးရန် အာဏာရှိကြောင်း ကြေညာသည်။',
    otherTermsDescription: 'ကုမ္ပဏီသည် ဤသဘောတူညီချက်၏ စည်းမျဉ်းများနှင့်အညီ အကောင့်လက်ကျန်ငွေ၏ ငွေကြေးဖြင့် ပေးဆောင်မည်။ နှစ်ဖက်စလုံးတွင် ဤသဘောတူညီချက်ကို လက်မှတ်ရေးထိုးရန် အခွင့်အရေးရှိပြီး၊ မည်သည့်ဘက်ကမျှ တတိယပါတီများ၏ အခွင့်အရေးများကို ချိုးဖောက်ခြင်း သို့မဟုတ် နှစ်ဖက်ကြား အခြား သဘောတူညီချက်များကို ချိုးဖောက်ခြင်း မပြုရပါ။',
    governingLawDescription: 'ဤသဘောတူညီချက်ကို ငွေချေးယူသူ တည်ရှိရာ နိုင်ငံ/ဒေသ၏ ဥပဒေများနှင့်အညီ ရှင်းလင်းဖောြပြီး အကောင်အထည်ဖော်မည် ဖြစ်သည်။',
    completeAgreementDescription: 'နှစ်ဖက်စလုံးသည် ဤစာရွက်စာတမ်းသည် နှစ်ဖက်ကြား ပြည့်စုံသော သဘောတူညီချက်ကို ဖွဲ့စည်းသည်ဟု သဘောတူသည်။ နှစ်ဖက်စလုံးသည် ထပ်မံ သဘောတူသည်မှာ ဤသဘောတူညီချက်၏ စည်းမျဉ်းများတွင် မည်သည့် ပြောင်းလဲမှု၊ ဖြည့်စွက်မှု သို့မဟုတ် ပြင်ဆင်မှုကိုမဆို စာဖြင့် ရေးသားပြီး အာဏာတည်မီ နှစ်ဖက်စလုံးက လက်မှတ်ရေးထိုးရမည် ဖြစ်သည်။',
