    legalEffectDescription: 'यह समझौता दोनों पक्षों के लिए कानूनी रूप से बाध्यकारी है और संयुक्त राज्य अमेरिका और यूरोप के भीतर हस्ताक्षरित और प्रभावी हो सकता है। दोनों पक्ष घोषणा करते हैं कि उनके पास इस समझौते पर हस्ताक्षर करने का अधिकार है।',
    otherTermsDescription: 'कंपनी इस समझौते की शर्तों के अनुसार खाता शेष की मुद्रा में भुगतान करेगी। दोनों पक्षों को इस समझौते पर हस्ताक्षर करने का अधिकार है, और कोई भी पक्ष तीसरे पक्ष के अधिकारों का उल्लंघन नहीं करेगा या पक्षों के बीच अन्य समझौतों का उल्लंघन नहीं करेगा।',
    governingLawDescription: 'इस समझौते की व्याख्या और प्रवर्तन उधारकर्ता के स्थित देश/क्षेत्र के कानूनों के अनुसार किया जाएगा।',
